//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_instruct(value: *mut SysPropStructSplit_Data_Model::StructXY) -> bool;
  fn get_instruct_num_invalid() -> u64;
  fn put_sv_last_x(value: *mut i32) -> bool;
  fn is_injection_enabled() -> bool;
  fn get_inj_sv_last_x(value: *mut i32) -> bool;
  fn is_monitoring_enabled() -> bool;
}

pub fn unsafe_get_instruct() -> SysPropStructSplit_Data_Model::StructXY
{
  unsafe {
    let value: *mut SysPropStructSplit_Data_Model::StructXY = &mut SysPropStructSplit_Data_Model::StructXY::default();
    get_instruct(value);
    return *value;
  }
}

pub fn unsafe_get_instruct_num_invalid() -> u64
{
  unsafe {
    return get_instruct_num_invalid();
  }
}

pub fn unsafe_put_sv_last_x(value: &i32) -> bool
{
  unsafe {
    return put_sv_last_x(value as *const i32 as *mut i32);
  }
}

pub fn unsafe_is_injection_enabled() -> bool
{
  unsafe {
    return is_injection_enabled();
  }
}

pub fn unsafe_get_inj_sv_last_x() -> Option<i32>
{
  unsafe {
    let mut value: i32 = i32::default();
    if get_inj_sv_last_x(&mut value) {
      return Some(value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_is_monitoring_enabled() -> bool
{
  unsafe {
    return is_monitoring_enabled();
  }
}

