#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_instruct: Mutex<Option<SysPropStructSplit_Data_Model::StructXY>> = Mutex::new(None);
  pub static ref OUT_sv_last_x: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref INJECTION_ENABLED: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref INJ_SV_last_x: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref MONITORING_ENABLED: Mutex<Option<bool>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_instruct.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_sv_last_x.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *INJECTION_ENABLED.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *INJ_SV_last_x.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *MONITORING_ENABLED.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_instruct(value: *mut SysPropStructSplit_Data_Model::StructXY) -> bool
{
  unsafe {
    let guard = IN_instruct.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_instruct_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn put_sv_last_x(value: *mut i32) -> bool
{
  unsafe {
    *OUT_sv_last_x.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn is_injection_enabled() -> bool
{
  unsafe {
    match *INJECTION_ENABLED.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => return v,
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn get_inj_sv_last_x(value: *mut i32) -> bool
{
  unsafe {
    match *INJ_SV_last_x.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn is_monitoring_enabled() -> bool
{
  unsafe {
    match *MONITORING_ENABLED.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => return v,
      None => return false,
    }
  }
}
